def insertion_point(sorted_nums, target):
    """
    Returns the leftmost index at which target can be inserted while keeping the list sorted.
    Uses binary search.

    Parameters:
    sorted_nums (list): List of comparable elements.
    target (int): Value to search for.

    Returns:
    int: Leftmost index where target can be inserted.

    Raises:
    ValueError: If target is not comparable or list is empty.
    """
    if not sorted_nums:
        raise ValueError("List cannot be empty.")

    if not isinstance(sorted_nums, list):
        raise TypeError("Input must be a list.")

    if not isinstance(target, int) or not isinstance(target, (int, float)):
        raise TypeError("target must be an integer or float.")

    if target < sorted_nums[0] or target > sorted_nums[-1]:
        raise ValueError("target must be within the range of the list.")

    left, right = 0, len(sorted_nums) - 1
    while left < right:
        mid = (left + right) // 2
        if sorted_nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left
